package com.vandorlabs.neoforge.programmer;
import com.google.gson.*;
import com.vandorlabs.neoforge.credentials.NativeCredentialItems;
import com.vandorlabs.programmer.ProgrammerStatus;
import io.netty.buffer.Unpooled;
import java.nio.file.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.core.component.DataComponents;
import net.minecraft.world.level.GameType;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
/** Released counter timeline under reload, clock correction, actual frozen ticks and low TPS. */
@EventBusSubscriber(modid="vandorlabs")
public final class ProgrammerTimelineChecks {
 private static JsonArray expected;private static int checks,freezeFrames,worldFrames;private static final NativeProgrammerEntity[] owners=new NativeProgrammerEntity[2],mirrors=new NativeProgrammerEntity[2];private static final CompoundTag[] baselines=new CompoundTag[2];private static final Object[] layouts=new Object[2];private static final int[] indices={7,43},warmup=new int[2];private static ServerLevel reading;private static long started;private static boolean armed;private static int plannedTicks;
 private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Programmer timeline: "+why);}
 private static void source()throws Exception{if(expected==null){var raw=JsonParser.parseString(Files.readString(Path.of(System.getenv("VANDOR_PROGRAMMER_INVENTORY_REFERENCE")))).getAsJsonObject();need(raw.get("golden").getAsString().equals("488ea87cd420cc0f0520ed3e1f21d54d44ac393d240743099698485ae8b3f678"),"frozen Source inventory/timer corpus");expected=raw.getAsJsonArray("timers");need(expected.size()==86,"all actual Source timer ticks");}}
 private static boolean matches(NativeProgrammerEntity owner,int tick){var row=expected.get(Math.min(tick,85)).getAsJsonObject();return owner.writing()==row.get("writing").getAsInt()&&owner.complete()==row.get("complete").getAsInt()&&owner.status().name().equals(row.get("status").getAsString());}
 private static void clock(ServerLevel level,long tick){((net.minecraft.world.level.storage.ServerLevelData)level.getLevelData()).setGameTime(tick);}
 private static NativeProgrammerEntity program(ServerLevel level,NativeProgrammerBlock block,ServerPlayer actor,BlockPos root,int id){for(int part=0;part<4;part++){var pos=NativeProgrammerBlock.cell(root,Direction.NORTH,part);level.getChunkAt(pos);level.setBlock(pos,block.defaultBlockState().setValue(NativeProgrammerBlock.PART,part),3);}var owner=(NativeProgrammerEntity)level.getBlockEntity(root);actor.setGameMode(GameType.SURVIVAL);actor.setPos(root.getX()+.5,root.getY(),root.getZ()-2);owner.setItem(0,NativeCredentialItems.dataChip(4));var input=NativeCredentialItems.dataChip(0);var tag=new CompoundTag();tag.putString("TimelineOwner","PRIVATE_TIMELINE_"+id);input.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));owner.setItem(1,input);need(owner.configure(actor,new NativeProgrammerDraft(false,true,"Timer "+id,List.of("Retained journal text")))&&owner.program(actor),"actual authorized Program starts timeline");return owner;}
 private static CompoundTag packet(NativeProgrammerEntity owner){var buffer=new RegistryFriendlyByteBuf(Unpooled.buffer(),owner.getLevel().registryAccess());try{var packet=owner.getUpdatePacket();ClientboundBlockEntityDataPacket.STREAM_CODEC.encode(buffer,packet);var decoded=ClientboundBlockEntityDataPacket.STREAM_CODEC.decode(buffer);need(!buffer.isReadable()&&decoded.getTag().equals(packet.getTag()),"actual packet timer round trip");need(!decoded.getTag().toString().contains("PRIVATE_TIMELINE_"),"timer projection excludes physical private item data");return decoded.getTag();}finally{buffer.release();}}
 private static void ownership(NativeProgrammerEntity owner,int id){need(owner.getItem(0).getCount()==1&&owner.getItem(1).isEmpty()&&owner.getItem(2).getCount()==1,"timer retains sole Master/result ownership");need(owner.getItem(2).getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().getString("TimelineOwner").equals("PRIVATE_TIMELINE_"+id),"complete physical result data survives timer/restart");}
 static void write(ServerLevel level,NativeProgrammerBlock block,ServerPlayer actor,BlockPos base)throws Exception{source();long time=level.getGameTime();var owner=program(level,block,actor,base,0);var mirror=new NativeProgrammerEntity(owner.getType(),base,owner.getBlockState());var baseline=packet(owner);mirror.loadWithComponents(baseline,level.registryAccess());Object layout=mirror.journalView().journal;try{for(int tick=0;tick<86;tick++){if(tick==3)clock(level,time+1000000);if(tick==11)clock(level,time-1000000);if(tick==7){var snapshot=owner.saveWithoutMetadata(level.registryAccess());owner.loadWithComponents(snapshot,level.registryAccess());}need(matches(owner,tick),"all Source counters/status tick="+tick);if(tick==20||tick==80)mirror.loadWithComponents(packet(owner),level.registryAccess());for(int repeat=0;repeat<16;repeat++)mirror.loadWithComponents(baseline,level.registryAccess());need(mirror.status()==owner.status()&&mirror.journalView().journal==layout&&mirror.getItem(0).isEmpty(),"delayed/repeated packets preserve phase/layout and cannot become owner tick="+tick);owner.tick();}ownership(owner,0);}finally{clock(level,time);level.removeBlock(base,false);}
  for(int id=0;id<2;id++){var saved=program(level,block,actor,base.east(8+id*8),id+1);for(int tick=0;tick<indices[id];tick++)saved.tick();need(matches(saved,indices[id]),"writing/complete checkpoint before save");ownership(saved,id+1);}System.out.println("[vandorlabs][programmer-timeline] write PASS checks="+checks+" Source86/corrections/private-reread/repeated-delayed-packets");}
 static void load(ServerLevel level,BlockPos base)throws Exception{source();for(int id=0;id<2;id++){var pos=base.east(8+id*8);level.setChunkForced(pos.getX()>>4,pos.getZ()>>4,true);level.getChunkAt(pos);owners[id]=(NativeProgrammerEntity)level.getBlockEntity(pos);need(matches(owners[id],indices[id]),"restart loads exact counter before first tick");ownership(owners[id],id+1);baselines[id]=owners[id].getUpdateTag(level.registryAccess());mirrors[id]=new NativeProgrammerEntity(owners[id].getType(),pos,owners[id].getBlockState());mirrors[id].loadWithComponents(baselines[id],level.registryAccess());layouts[id]=mirrors[id].journalView().journal;}reading=level;}
 @SubscribeEvent public static void ready(net.neoforged.neoforge.event.tick.ServerTickEvent.Pre event){if(reading==null||armed||event.getServer()!=reading.getServer())return;for(var owner:owners){var pos=owner.getBlockPos();if(!reading.areEntitiesLoaded(net.minecraft.world.level.ChunkPos.asLong(pos))||!reading.getChunkAt(pos).getFullStatus().isOrAfter(net.minecraft.server.level.FullChunkStatus.BLOCK_TICKING))return;}for(int id=0;id<2;id++){owners[id]=(NativeProgrammerEntity)reading.getBlockEntity(owners[id].getBlockPos());int index=indices[id];while(index<80&&!matches(owners[id],index))index++;need(matches(owners[id],index),"loaded installed owner has a Source timeline before freeze");indices[id]=index;ownership(owners[id],id+1);}plannedTicks=Math.max(80-indices[0],80-indices[1]);armed=true;event.getServer().tickRateManager().setFrozen(true);}
 @SubscribeEvent public static void paused(net.neoforged.neoforge.event.tick.ServerTickEvent.Post event){if(reading==null||event.getServer()!=reading.getServer()||!armed||freezeFrames>=3)return;for(int id=0;id<2;id++)need(matches(owners[id],indices[id]),"actual frozen server leaves saved counters unchanged");if(++freezeFrames==3){event.getServer().tickRateManager().setFrozen(false);event.getServer().tickRateManager().setTickRate(5F);started=System.nanoTime();}}
 static boolean readReady(ServerLevel level){if(reading!=level)return true;if(!armed||freezeFrames<3)return false;need(++worldFrames<100,"low-TPS timeline timeout");for(int id=0;id<2;id++){if(indices[id]<80){if(matches(owners[id],indices[id])&&warmup[id]<5&&indices[id]==(id==0?7:43))warmup[id]++;else{indices[id]++;need(matches(owners[id],indices[id]),"one Source counter step per actual low-TPS tick owner="+id+" index="+indices[id]+" actualWriting="+owners[id].writing()+" actualComplete="+owners[id].complete()+" status="+owners[id].status()+" inert="+owners[id].inert()+" installed="+(level.getBlockEntity(owners[id].getBlockPos())==owners[id]));}}var update=owners[id].getUpdateTag(level.registryAccess());for(int repeat=0;repeat<16;repeat++)mirrors[id].loadWithComponents(update,level.registryAccess());mirrors[id].loadWithComponents(baselines[id],level.registryAccess());need(mirrors[id].status()==owners[id].status()&&mirrors[id].journalView().journal==layouts[id]&&mirrors[id].getItem(2).isEmpty(),"low-TPS repeated/old DTO phase/layout/ownership");ownership(owners[id],id+1);}if(indices[0]<80||indices[1]<80)return false;long millis=(System.nanoTime()-started)/1000000;need(millis>=plannedTicks*120L,"actual5TPS interval measured="+millis+" plannedTicks="+plannedTicks);level.getServer().tickRateManager().setTickRate(20F);reading=null;System.out.println("[vandorlabs][programmer-timeline] read PASS checks="+checks+" frozenFrames="+freezeFrames+" lowTPS=5 worldFrames="+worldFrames+" elapsedMs="+millis);return true;}
}
